"""Bundle the exact RTL and independent self-checking TB for a remote compiler."""
from pathlib import Path

HERE = Path(__file__).resolve().parent
rtl = (HERE / 'prep_216_220_sequential.sv').read_text(encoding='utf-8')
tb = (HERE / 'prep_216_220_sequential_tb_body.sv').read_text(encoding='utf-8')
(HERE / 'prep_216_220_sequential_tb.sv').write_text(
    '// Generated by build_batch20_sequential_tb.py; edit RTL and TB body sources.\n' + rtl + '\n' + tb,
    encoding='utf-8')
print('Wrote self-contained prep_216_220_sequential_tb.sv')
